<?php
// Database connection. Owner: Member 1.
// Default XAMPP settings: user root, no password. Everyone keeps THIS file identical.
// If your MySQL needs a different user/password/port, do NOT edit this file.
// Copy config/db.local.example.php to config/db.local.php and change it there
// (db.local.php is ignored by Git, so it never causes merge conflicts).
if (file_exists(__DIR__ . '/db.local.php')) {
    require __DIR__ . '/db.local.php';
}
defined('DB_HOST') || define('DB_HOST', '127.0.0.1');
defined('DB_PORT') || define('DB_PORT', '3306');
defined('DB_NAME') || define('DB_NAME', 'dolphin_crm');   // never change the database name
defined('DB_USER') || define('DB_USER', 'root');
defined('DB_PASS') || define('DB_PASS', '');

// Everyone uses db() to get the connection:  $pdo = db();
function db(): PDO
{
    static $pdo = null;
    if ($pdo === null) {
        try {
            $pdo = new PDO(
                'mysql:host=' . DB_HOST . ';port=' . DB_PORT . ';dbname=' . DB_NAME . ';charset=utf8mb4',
                DB_USER,
                DB_PASS,
                [
                    PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
                    PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                ]
            );
        } catch (PDOException $e) {
            http_response_code(500);
            header('Content-Type: application/json');
            echo json_encode([
                'success' => false,
                'message' => 'Database connection failed. Is MySQL running, and did you import schema.sql?',
            ]);
            exit;
        }
    }
    return $pdo;
}
